create or replace function audit.log_change () returns trigger language plpgsql security definer set search_path = audit, public as $$ begin insert into audit.events (tenant_id, actor_id, table_name, operation, record_id, payload) values ( coalesce(new.tenant_id, old.tenant_id), auth.uid(), tg_table_name, tg_op, coalesce(new.id, old.id)::text, case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end ); return coalesce(new, old); end; $$;
